    71	export function classifyReviewerExecutionAuthority(args: {
    72	  executionMode: 'native-host' | 'cross-provider-cli';
    73	  assuranceLevel: 'ordinary-review' | 'degraded-single-host';
    74	  hasManagedEvidenceBinding: boolean;
