    76	  if (args.assuranceLevel === 'degraded-single-host') {
    77	    return {
    78	      classification: 'degraded-single-host-local-only',
    79	      directSignedReviewAllowed: false,
    80	      managedReceiptRequired: false,
    81	      reviewGatePath: 'local-host-verdict-only',
    82	    };
    83	  }
    84	  if (args.executionMode === 'cross-provider-cli') {
    85	    return args.hasManagedEvidenceBinding
    86	      ? {
    87	        classification: 'managed-cross-provider-receipt',
    88	        directSignedReviewAllowed: false,
    89	        managedReceiptRequired: true,
    90	        reviewGatePath: 'managed-receipt',
    91	      }
    92	      : {
    93	        classification: 'cross-provider-advisory-only',
    94	        directSignedReviewAllowed: false,
    95	        managedReceiptRequired: true,
    96	        reviewGatePath: 'none',
    97	      };
    98	  }
    99	  if (args.hasManagedEvidenceBinding) {
   100	    return {
   101	      classification: 'cross-provider-advisory-only',
   102	      directSignedReviewAllowed: false,
   103	      managedReceiptRequired: true,
   104	      reviewGatePath: 'none',
   105	    };
   106	  }
   107	  return {
   108	    classification: 'native-host-signed-review',
   109	    directSignedReviewAllowed: true,
   110	    managedReceiptRequired: false,
   111	    reviewGatePath: 'direct-signed-review',
   112	  };
